mapper.select:
SELECT * FROM oa_consumable_request WHERE tenant_id = #{tenantId} AND deleted = 0
AND applicant_id = #{applicantId}
AND status IN ('APPROVED', 'ISSUED')
AND status = #{query.status}
AND request_no LIKE CONCAT('%', #{query.requestNo}, '%')
AND applicant_name LIKE CONCAT('%', #{query.applicantName}, '%')
AND dept_id = #{query.deptId}
AND applicant_id = #{query.applicantId}
AND create_time >= #{query.from}
AND create_time < #{query.to}
ORDER BY request_id DESC

SELECT * FROM oa_trace_event WHERE tenant_id = #{tenantId} AND business_type = 'OA_CONSUMABLE_REQUEST'
    AND event_type = #{eventType} AND event_content = #{key}
AND business_id = #{businessId}
ORDER BY id DESC LIMIT 1
